"""Record polygon-fan conversion risks, without claiming a native Max run."""
import json
from pathlib import Path
from collections import defaultdict,Counter
import numpy as np
from dt_ai.ops.inv_xview import vertex_pairs


def inspect(v,faces):
    inc=defaultdict(list)
    for i,f in enumerate(faces):
        for a in f:inc[int(a)].append(i)
    out=[]; vv=list(v)
    for a,ids in inc.items():
        parents={i:i for i in ids}
        def find(i):
            while parents[i]!=i:
                parents[i]=parents[parents[i]];i=parents[i]
            return i
        edges=defaultdict(list)
        for i in ids:
            f=faces[i];pos=list(f).index(a)
            for b in (f[pos-1],f[(pos+1)%len(f)]):edges[int(b)].append(i)
        for uses in edges.values():
            for i in uses[1:]: parents[find(i)]=find(uses[0])
        groups=defaultdict(list)
        for i in ids:groups[find(i)].append(i)
        if len(groups)>1:
            out.append({'vertex':a,'xyz':v[a].tolist(),'fan_faces':list(groups.values())})
            for _ in range(len(groups)-1):vv.append(v[a].copy())
    pa,pb,dist=vertex_pairs(np.array(vv),.002)
    return {'fan_split_risk_vertices':len(out),'fan_split_risks':out,'simulated_after_fan_split_vertex_pairs':len(pa),'simulated_after_fan_split_affected_vertices':len(set(pa)|set(pb)),'not_native_max':True}

p=json.loads(Path('tmp/paired-v014.json').read_text())
n=np.load('tmp/construction-probe.npz')
result={'paired':inspect(np.array(p['verts']),p['faces']),'construction':inspect(n['verts'],n['faces'])}
Path('tmp/bowtie-conversion-risk.json').write_text(json.dumps(result,indent=2))
for k,v in result.items(): print(k,{a:b for a,b in v.items() if a!='fan_split_risks'})
